<script setup>
import { ref } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import Layout from '@/Layouts/AdminLayout.vue';
defineProps({applications:Array,requirements:{type:Object,default:()=>({})}});
const detailLabels={applicantType:'Applicant type',businessName:'Registered business',relationship:'Ownership / authority',serviceCategory:'Service category',skills:'Skills and qualifications',experienceYears:'Years of experience'};
const titles={spaces:'Landlord / property merchant',haul:'Vehicle owner',raketeer:'Freelance service provider'};
const active=ref(null); const form=useForm({version:null,status:'approved',reviewNote:''});
function review(item,status){active.value=item;form.version=item.application?.version||null;form.clearErrors();form.status=status;form.reviewNote='';}
function submit(){form.post(`/admin/approvals/${active.value.userId}/${active.value.service}`,{preserveScroll:true,onSuccess:()=>active.value=null});}
</script>
<template><Layout><template #header><h1 class="approvals-heading">Role approvals</h1></template><Head title="Review provider applications"/><section class="admin-approvals"><p class="workspace-kicker">Administration</p><h1>Provider applications</h1><p>Review each role independently. Supporting documents are private.</p><div v-if="!applications.length" class="workspace-empty"><h2>All caught up.</h2><p>No provider applications are waiting for review.</p></div><article v-for="item in applications" :key="item.userId+item.service" class="application-review"><div class="role-title"><h2>{{ item.application?.displayName || item.name }}</h2><span class="availability-tag draft">{{ titles[item.service] }}</span></div><p>{{ item.name }} · {{ item.email }}</p><template v-if="item.application"><dl><dt>Phone</dt><dd>{{ item.application.phone }}</dd><dt>Primary area</dt><dd>{{ item.application.area }}</dd><dt>Offering</dt><dd>{{ item.application.description }}</dd></dl><dl><template v-for="(label,key) in detailLabels" :key="key"><template v-if="item.application.details?.[key] != null && item.application.details[key] !== ''"><dt>{{ label }}</dt><dd>{{ item.application.details[key] }}</dd></template></template></dl><div class="review-documents"><a v-for="doc in item.application.documents" :key="doc.url" :href="doc.url" class="document-link">{{ requirements[item.service]?.[doc.type]?.label || 'Supporting document' }} · {{ doc.name }} ↗ <span v-if="doc.reference"> · {{ doc.reference }}</span><span v-if="doc.expiresAt"> · Expires {{ doc.expiresAt }}</span></a></div></template><p v-else class="role-notice">This older request has no supporting details. The user must complete the application before approval.</p><div class="actions"><button v-if="item.application" class="button primary" @click="review(item,'approved')">Approve role</button><button class="button" @click="review(item,'rejected')">Request an update</button></div><form v-if="active?.userId===item.userId&&active?.service===item.service" class="review-decision" @submit.prevent="submit"><h3>{{ form.status==='approved'?'Confirm approval':'Explain what needs updating' }}</h3><label>Review note {{ form.status==='approved'?'(optional)':'' }}<textarea v-model="form.reviewNote" :required="form.status==='rejected'" maxlength="2000" rows="3"/></label><p v-for="(error,key) in form.errors" :key="key" class="error" role="alert">{{ error }}</p><div class="actions"><button class="button primary" :disabled="form.processing">{{ form.processing?'Saving…':'Confirm decision' }}</button><button type="button" class="button" :disabled="form.processing" @click="active=null">Cancel</button></div></form></article></section></Layout></template>

<style scoped>
.approvals-heading{font-size:24px;font-weight:700}.admin-approvals{max-width:1040px;margin:auto}.admin-approvals>h1{font-size:26px;font-weight:700;margin:8px 0}.admin-approvals>p{font-size:14px;color:#637b76;line-height:1.6}.workspace-kicker{font-size:11px!important;font-weight:700;letter-spacing:.06em;color:#137671!important}.application-review{background:white;border:1px solid #dce7e4;border-radius:14px;padding:24px;margin-top:24px}.role-title{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.role-title h2{font-size:20px;font-weight:700}.availability-tag{background:#fff3db;color:#825c1b;border-radius:6px;padding:6px 10px;font-size:11px}.application-review>p{font-size:13px;color:#637b76;margin:12px 0;overflow-wrap:anywhere}.application-review dl{display:grid;grid-template-columns:160px minmax(0,1fr);gap:10px 18px;font-size:13px;margin:20px 0}.application-review dt{color:#637b76}.application-review dd{overflow-wrap:anywhere}.review-documents{display:grid;gap:10px;margin:20px 0}.document-link{display:block;background:#f3f8f5;border:1px solid #dce7e4;border-radius:8px;padding:12px;font-size:13px;color:#137671;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}.button{min-height:44px;padding:10px 16px;border:1px solid #b7d8d0;border-radius:8px;font-size:13px;font-weight:700;color:#12675f}.button.primary{background:#137671;color:white;border-color:#137671}.button:disabled{opacity:.5}.review-decision{margin-top:20px;border-top:1px solid #dce7e4;padding-top:20px}.review-decision h3{font-weight:700;margin-bottom:14px}.review-decision label{display:grid;gap:8px;font-size:13px}.review-decision textarea{width:100%;border:1px solid #b7d8d0;border-radius:8px;padding:12px;background:white}.error{color:#b42318;font-size:13px}.workspace-empty{margin-top:24px;padding:40px 24px;border:1px dashed #b7d8d0;border-radius:12px;text-align:center}.workspace-empty h2{font-size:20px;font-weight:700}.admin-approvals :is(a,button,textarea):focus-visible{outline:2px solid #137671;outline-offset:3px}@media(max-width:600px){.application-review{padding:18px}.application-review dl{grid-template-columns:1fr;gap:6px}.application-review dd{margin-bottom:10px}}
</style>
